@lru_cache(None)
def ways(cur, seen16):
    if cur == 21:
        return 0
    if cur > 60:
        return 0
    if cur == 60:
        return 1 if seen16 else 0
    total = ways(cur + 1, seen16 or cur + 1 == 16)
    total += ways(cur * 3, seen16 or cur * 3 == 16)
    total += ways(cur * 4, seen16 or cur * 4 == 16)
    return total

